"""Summarize node sequence gaps without changing the node."""
import json
from pathlib import Path
import re
import stat
import sys


CHANNELS = ("obs", "must")


def reject_constant(value):
    raise ValueError(value)


def read_json(data):
    return json.loads(data, parse_constant=reject_constant)


def load_state(node, bad):
    fields = {channel: None for channel in CHANNELS}
    path = node / "state.json"
    if not (path.exists() or path.is_symlink()):
        return fields
    invalid = False
    try:
        state = read_json(path.read_bytes())
        if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
            raise ValueError("invalid state")
        for channel in CHANNELS:
            value = state["channels"].get(channel)
            if (isinstance(value, dict)
                    and type(value.get("next_seq")) is int
                    and (channel != "must" or type(value.get("acked_upto")) is int)):
                fields[channel] = value
            else:
                invalid = True
    except (OSError, ValueError, UnicodeError):
        invalid = True
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    return fields


def records(path, bad):
    counts = {}
    data = path.read_bytes()
    parts = data.split(b"\n")
    for line_number, line in enumerate(parts[:-1], 1):
        try:
            value = read_json(line)
        except (ValueError, UnicodeError):
            bad.append({"file": path.name, "line": line_number, "why": "bad_json"})
            continue
        if not isinstance(value, dict) or type(value.get("seq")) is not int or value["seq"] < 1:
            bad.append({"file": path.name, "line": line_number, "why": "no_seq"})
            continue
        seq = value["seq"]
        counts[seq] = counts.get(seq, 0) + 1
    if parts[-1]:
        bad.append({"file": path.name, "line": len(parts), "why": "torn"})
    return counts


def summarize(node):
    bad = []
    state = load_state(node, bad)
    files = [path for path in node.iterdir() if stat.S_ISREG(path.lstat().st_mode)]
    channels = {}
    for channel in CHANNELS:
        pattern = re.compile(r"%s\.([0-9]{12})\.jsonl" % channel)
        segments = []
        active = None
        for path in files:
            match = pattern.fullmatch(path.name)
            if match:
                segments.append((int(match.group(1)), path))
            elif path.name == channel + ".active.jsonl":
                active = path
        ordered = [path for _, path in sorted(segments, key=lambda item: item[0])]
        if active is not None:
            ordered.append(active)
        counts = {}
        for path in ordered:
            for seq, amount in records(path, bad).items():
                counts[seq] = counts.get(seq, 0) + amount
        seqs = sorted(counts)
        first = seqs[0] if seqs else None
        last = seqs[-1] if seqs else None
        value = state[channel]
        next_seq = value["next_seq"] if value is not None else None
        channels[channel] = {
            "count": sum(counts.values()),
            "first": first,
            "last": last,
            "missing": [[left + 1, right - 1] for left, right in zip(seqs, seqs[1:]) if right > left + 1],
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": next_seq,
            "unacked": (sum(seq > value["acked_upto"] for seq in seqs)
                        if channel == "must" and value is not None else None),
            "stale_next": (next_seq != last + 1 if value is not None and last is not None else None),
        }
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        return 2
    print(json.dumps(summarize(Path(args[0])), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
